# -*- coding: utf-8 -*-
from app.learning.question_helper import make_mc

def get_questions_cinematica_extra():
    # 20 preguntas ya definidas
    q = []
    # Ejercicios
    q.append(make_mc('Un ciclista en MRU viaja a 8 m/s durante 45 s. ¿Que distancia recorre?', '360 m', ['320 m', '400 m', '280 m'], 'd = v*t = 8*45 = 360 m.', 'd = 360 m.', 'basic', 1150, '¿Que relacion vincula velocidad, tiempo y distancia en MRU?'))
    q.append(make_mc('Un movil parte del reposo con a = 2.5 m/s2 constante. ¿Rapidez a los 6.0 s?', '15.0 m/s', ['12.5 m/s', '17.5 m/s', '10.0 m/s'], 'v = a*t = 15 m/s.', 'v = 15 m/s.', 'basic', 1180, '¿Que formula relaciona aceleracion, tiempo y velocidad inicial nula?'))
    q.append(make_mc('Un auto a 20 m/s frena hasta detenerse en 50 m. ¿Modulo de aceleracion?', '4.0 m/s²', ['2.0 m/s²', '5.0 m/s²', '8.0 m/s²'], 'vf^2 = v0^2 - 2ad -> a = 4 m/s2.', 'a = 4 m/s2.', 'intermediate', 1220, 'Aplica la ecuacion de Torricelli independiente del tiempo.'))
    q.append(make_mc('Se lanza hacia arriba un cuerpo a 30 m/s (g = 10 m/s2). ¿Altura maxima?', '45.0 m', ['30.0 m', '60.0 m', '90.0 m'], 'Hmax = v0^2 / (2g) = 45 m.', 'Hmax = 45 m.', 'intermediate', 1230, '¿Que valor tiene la velocidad vertical en el punto mas alto?'))
    q.append(make_mc('¿Tiempo de caida libre desde 80 m de altura? (g = 10 m/s2)', '4.0 s', ['2.0 s', '5.5 s', '8.0 s'], 'h = 0.5gt^2 -> t = 4 s.', 't = 4 s.', 'basic', 1170, 'Despeja el tiempo a partir de la ecuacion de caida libre.'))
    q.append(make_mc('Un tren pasa de 10 m/s a 30 m/s en 5.0 s uniformemente. ¿Distancia?', '100 m', ['120 m', '80 m', '150 m'], 'd = v_media * t = 20 * 5 = 100 m.', 'd = 100 m.', 'intermediate', 1210, 'Multiplica la velocidad media por el tiempo.'))
    q.append(make_mc('Vector desplazamiento con dx = 6.0 m y dy = 8.0 m. ¿Modulo total?', '10.0 m', ['14.0 m', '7.0 m', '12.0 m'], 'Modulo = sqrt(36 + 64) = 10 m.', 'd = 10 m.', 'basic', 1160, 'Aplica el teorema de Pitagoras a las componentes ortogonales.'))
    q.append(make_mc('Movil parte de x = 12 m con v = -3 m/s constante. ¿Cuando cruza x = 0?', '4.0 s', ['3.0 s', '6.0 s', '2.5 s'], '0 = 12 - 3t -> t = 4 s.', 't = 4 s.', 'basic', 1150, 'Iguala la ecuacion horaria de posicion a cero.'))
    q.append(make_mc('En grafico v-t, la recta marca 15 m/s constante entre t = 2 s y 8 s. ¿Area?', '90 m', ['120 m', '60 m', '75 m'], 'Area = 6 * 15 = 90 m.', 'Area = 90 m.', 'intermediate', 1200, 'Calcula el area del rectangulo bajo la curva de velocidad.'))
    q.append(make_mc('Dos autos parten opuestos desde el mismo punto a 15 m/s y 25 m/s. ¿Separacion a 10 s?', '400 m', ['250 m', '100 m', '300 m'], 'd = (15+25)*10 = 400 m.', 'd = 400 m.', 'intermediate', 1210, 'Suma las distancias recorridas en sentidos opuestos.'))
    # Teoricas
    q.append(make_mc('En un grafico x(t), la pendiente de la recta tangente representa:', 'La velocidad instantanea del movil', ['La aceleracion media del movil', 'El desplazamiento acumulado', 'La fuerza aplicada'], 'Pendiente dx/dt es velocidad.', 'v = dx/dt.', 'basic', 1150, '¿Que razon de cambio espacial respecto al tiempo define la velocidad?'))
    q.append(make_mc('Si la velocidad es cero en un instante, ¿la aceleracion es obligadamente nula?', 'No, puede tener aceleracion no nula', ['Si, la aceleracion debe ser cero', 'Si, porque el objeto esta inmóvil', 'No, la aceleracion es infinita'], 'En altura maxima v=0 pero a = -g.', 'a puede ser distinta de cero.', 'intermediate', 1230, 'Pensa en el punto mas alto de un tiro vertical.'))
    q.append(make_mc('¿Que condicion define formalmente al MRUV?', 'Aceleracion constante y no nula', ['Velocidad constante y uniforme', 'Trayectoria parabolica plana', 'Aceleracion variable'], 'MRUV <=> a = constante.', 'a = constante.', 'basic', 1140, '¿Que magnitud cinematica permanece invariable en el MRUV?'))
    q.append(make_mc('El area bajo una curva aceleracion-tiempo a(t) representa:', 'El cambio de velocidad del movil', ['La posicion alcanzada', 'La distancia total', 'La fuerza resultante'], 'Integral de a dt = Delta v.', 'Delta v = area a(t).', 'intermediate', 1220, '¿Que magnitud resulta de multiplicar aceleracion por tiempo?'))
    q.append(make_mc('Si velocidad y aceleracion tienen signos opuestos, la rapidez:', 'Disminuye de forma progresiva', ['Aumenta de forma progresiva', 'Permanece constante', 'Se vuelve nula instantaneamente'], 'Signos contrarios implican frenado.', 'Rapidez decrece.', 'basic', 1160, '¿Que efecto produce una aceleracion opuesta a la marcha?'))
    q.append(make_mc('En tiro vertical libre sin aire, el tiempo de subida respecto al de bajada:', 'Son exactamente iguales entre si', ['El de subida es el doble', 'El de bajada es el doble', 'Depende de la masa'], 'Por simetria gravitatoria son iguales.', 't_subida = t_bajada.', 'basic', 1170, '¿Como influye que el modulo de g sea igual al subir y bajar?'))
    q.append(make_mc('La diferencia entre trayectoria y desplazamiento es:', 'La trayectoria es el camino y el desplazamiento un vector', ['La trayectoria es recta y el desplazamiento curvo', 'Ambos conceptos son identicos', 'La trayectoria es vectorial'], 'Trayectoria: curva; Desplazamiento: vector.', 'Delta r = rf - r0.', 'intermediate', 1210, '¿Cual magnitud depende del camino y cual une inicio con fin?'))
    q.append(make_mc('Una grafica x(t) con curvatura concava hacia arriba indica:', 'Aceleracion positiva constante', ['Aceleracion negativa constante', 'Velocidad uniforme', 'Aceleracion nula'], 'Concavidad positiva <=> a > 0.', 'a > 0.', 'intermediate', 1240, '¿Que signo de aceleracion corresponde a una curva hacia arriba?'))
    q.append(make_mc('Una aceleracion perpendicular a la velocidad en todo instante:', 'Modifica la direccion sin cambiar la rapidez', ['Aumenta la rapidez lineal', 'Frena al movil hasta pararlo', 'Invierte el sentido'], 'Aceleracion centripeta varia direccion.', 'Cambia direccion de v.', 'advanced', 1270, 'Si no hay componente tangencial, ¿puede cambiar el modulo?'))
    q.append(make_mc('El velocimetro de un automovil mide formalmente:', 'La rapidez escalar instantanea', ['La velocidad media vectorial', 'La aceleracion instantanea', 'El desplazamiento total'], 'Mide |v| sin orientacion.', 'Rapidez instantanea.', 'basic', 1140, '¿Indica el velocimetro hacia que punto cardinal viajas?'))
    return q


def get_questions_dinamica_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Cuerpo de 5.0 kg sobre piso liso recibe fuerza horizontal de 20 N. ¿Aceleracion?', '4.0 m/s²', ['2.5 m/s²', '5.0 m/s²', '10.0 m/s²'], 'a = 20 / 5 = 4 m/s2.', 'a = F/m = 4 m/s2.', 'basic', 1150, 'Aplica la Segunda Ley de Newton F = m*a.'))
    q.append(make_mc('Objeto de 8.0 kg pesa 78.4 N. ¿Cual es la gravedad local?', '9.8 m/s²', ['8.0 m/s²', '10.0 m/s²', '9.6 m/s²'], 'g = 78.4 / 8 = 9.8 m/s2.', 'g = P/m = 9.8 m/s2.', 'basic', 1140, 'Divide el peso entre la masa del objeto.'))
    q.append(make_mc('Bloque de 10 kg sobre superficie con μc = 0.30 (g = 10 m/s2). ¿Fuerza de rozamiento?', '30 N', ['3.0 N', '25 N', '33 N'], 'f_rc = 0.30 * 10 * 10 = 30 N.', 'f_rc = μc*N = 30 N.', 'basic', 1170, 'Multiplica el coeficiente cinetico por la normal.'))
    q.append(make_mc('Fuerza neta de 50 N actua sobre 25 kg en reposo durante 4.0 s. ¿Rapidez final?', '8.0 m/s', ['6.0 m/s', '10.0 m/s', '12.5 m/s'], 'a = 2 m/s2; v = 2 * 4 = 8 m/s.', 'v = a*t = 8 m/s.', 'intermediate', 1210, 'Halla la aceleracion y multiplicala por el tiempo.'))
    q.append(make_mc('Resorte con k = 200 N/m se comprime 0.05 m. ¿Fuerza elastica?', '10 N', ['4.0 N', '20 N', '40 N'], 'Fe = 200 * 0.05 = 10 N.', 'Fe = k*x = 10 N.', 'basic', 1160, 'Aplica la ley de Hooke multiplicando k por x.'))
    q.append(make_mc('Bloque de 4.0 kg baja por plano a 30° sin rozamiento (g = 10 m/s2). ¿Componente Px?', '20 N', ['40 N', '34.6 N', '10 N'], 'Px = 4 * 10 * sen(30) = 20 N.', 'Px = mg sen(30) = 20 N.', 'intermediate', 1220, 'Usa el seno del angulo para proyectar el peso en el plano.'))
    q.append(make_mc('Dos fuerzas ortogonales de 6.0 N y 8.0 N sobre 2.0 kg. ¿Aceleracion?', '5.0 m/s²', ['7.0 m/s²', '3.5 m/s²', '10.0 m/s²'], 'F_net = 10 N; a = 10 / 2 = 5 m/s2.', 'a = 10 / 2 = 5 m/s2.', 'intermediate', 1230, 'Calcula la resultante con Pitagoras y dividela por la masa.'))
    q.append(make_mc('Ascensor de 500 kg frena al bajar con a = 2 m/s2 hacia arriba (g = 10 m/s2). ¿Tension?', '6000 N', ['4000 N', '5000 N', '1000 N'], 'T = 500 * (10 + 2) = 6000 N.', 'T = m(g+a) = 6000 N.', 'advanced', 1260, 'Aplica Newton vertical considerando a hacia arriba.'))
    q.append(make_mc('Mover 50 kg requiere fuerza minima de 150 N (g = 10 m/s2). ¿Coeficiente μe?', '0.30', ['0.15', '0.45', '0.60'], 'μe = 150 / 500 = 0.30.', 'μe = F/N = 0.30.', 'intermediate', 1210, 'Divide la fuerza estatica maxima entre la normal.'))
    q.append(make_mc('Proyectil de 0.20 kg frena con fuerza de 50 N al penetrar madera. ¿Desaceleracion?', '250 m/s²', ['100 m/s²', '500 m/s²', '125 m/s²'], 'a = 50 / 0.20 = 250 m/s2.', 'a = F/m = 250 m/s2.', 'intermediate', 1220, 'Divide la fuerza de frenado entre la masa del proyectil.'))
    # Teoricas
    q.append(make_mc('Segun la Primera Ley de Newton, sin fuerzas externas netas un cuerpo conserva:', 'Su estado de reposo o MRU uniforme', ['Una aceleracion constante no nula', 'Un movimiento circular sin frenado', 'Una trayectoria espiral descendente'], 'Inercia: F_net = 0 implica v = constante.', 'F_net = 0 <=> v = constante.', 'basic', 1140, '¿Que predice el principio de inercia si la fuerza neta es cero?'))
    q.append(make_mc('El par de accion y reaccion de la Tercera Ley de Newton actua:', 'Siempre sobre dos cuerpos distintos', ['Siempre sobre el mismo objeto', 'Anulandose en el mismo objeto', 'Solo si los cuerpos se mueven'], 'Actuan sobre objetos distintos, no se anulan.', 'Accion y reaccion en cuerpos distintos.', 'basic', 1160, 'Si empujas la pared, ¿sobre quien actua cada fuerza?'))
    q.append(make_mc('La masa inercial de un objeto representa formalmente:', 'La medida cuantitativa de su inercia', ['La atraccion gravitatoria terrestre', 'El volumen espacial que ocupa', 'La lectura en dinamometro calibrado'], 'Mide la oposicion a cambiar de velocidad.', 'Masa inercial = resistencia a acelerar.', 'basic', 1150, '¿Que propiedad mide la oposicion al cambio de velocidad?'))
    q.append(make_mc('¿Por que el coeficiente estatico μe es mayor que el cinetico μc?', 'Porque las rugosidades encajan mas en reposo', ['Porque la normal disminuye al deslizarse', 'Porque la gravedad actua menos en reposo', 'Porque el area de contacto se anula'], 'En reposo las asperezas se traban con mas firmeza.', 'μe > μc por trabado estatico superficial.', 'intermediate', 1220, '¿Que requiere mas fuerza: iniciar el movimiento o mantenerlo?'))
    q.append(make_mc('Un vaso descansa en una mesa. ¿Reaccion a la fuerza peso del vaso?', 'La atraccion gravitatoria del vaso sobre la Tierra', ['La fuerza normal ejercida por la mesa', 'El rozamiento entre vaso y superficie', 'La fuerza de soporte de las patas'], 'Par del peso: atraccion gravitatoria hacia la Tierra.', 'Fuerza gravitatoria que el vaso hace a la Tierra.', 'advanced', 1260, 'El par debe ser de la misma naturaleza gravitatoria entre ambos cuerpos.'))
    q.append(make_mc('Una particula gira en curva a rapidez constante. ¿Actua una fuerza neta?', 'Si, una fuerza centripeta hacia el centro', ['No, porque la rapidez no esta cambiando', 'No, porque se encuentra en equilibrio', 'Solo si hay contacto con un fluido'], 'Variar la direccion implica aceleracion centripeta.', 'Giro curvo => fuerza centripeta no nula.', 'intermediate', 1220, '¿La velocidad cambia de orientacion al describir una curva?'))
    q.append(make_mc('Para que un bloque baje por un plano inclinado a rapidez constante:', 'El peso paralelo debe igualar al rozamiento', ['La normal debe anularse totalmente', 'No debe actuar gravedad sobre el bloque', 'El angulo debe ser de noventa grados'], 'Equilibrio dinamico: Px - f_rc = 0.', 'Px = f_rc para velocidad constante.', 'intermediate', 1210, '¿Que condicion de equilibrio exige la Primera Ley en el plano?'))
    q.append(make_mc('Si un astronauta en gravedad cero lanza una herramienta hacia adelante:', 'Retrocede hacia atras con menor aceleracion', ['Permanece inmovil en la misma posicion', 'Acelera hacia adelante junto a la pieza', 'Comienza a girar en su propio eje'], 'Tercera Ley: fuerza igual y opuesta hacia atras.', 'Accion y reaccion en sentido contrario.', 'basic', 1170, '¿Que predice la Tercera Ley sobre el emisor del empuje?'))
    q.append(make_mc('Al aumentar la inclinacion de un plano inclinado, la fuerza normal:', 'Disminuye conforme el coseno decrece', ['Aumenta conforme el seno se eleva', 'Permanece estrictamente constante', 'Se duplica al pasar los 45 grados'], 'N = mg*cos(θ). cos(θ) decrece con el angulo.', 'N disminuye al crecer la inclinacion.', 'intermediate', 1230, '¿Que ocurre con cos(θ) cuando el angulo sube hacia 90°?'))
    q.append(make_mc('La unidad del Sistema Internacional para la fuerza es el Newton (N), igual a:', 'kg·m/s²', ['kg·m²/s²', 'kg·m/s', 'Joule por segundo'], '1 N = 1 kg * 1 m/s2.', '1 N = 1 kg·m/s².', 'basic', 1140, 'Combina masa y aceleracion en la Segunda Ley de Newton.'))
    return q

def get_questions_trabajo_energia_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Fuerza de 40 N empuja una caja 5.0 m en su misma direccion. ¿Trabajo realizado?', '200 J', ['160 J', '240 J', '80 J'], 'W = 40 * 5 = 200 J.', 'W = 200 J.', 'basic', 1150, 'Multiplica fuerza por desplazamiento cuando son paralelos.'))
    q.append(make_mc('¿Cual es la energia cinetica de un automovil de 1200 kg a 20 m/s?', '240 kJ', ['120 kJ', '480 kJ', '24 kJ'], 'Ek = 0.5 * 1200 * 400 = 240 kJ.', 'Ek = 240000 J.', 'basic', 1170, 'Calcula un medio de la masa por el cuadrado de la rapidez.'))
    q.append(make_mc('Bloque de 3.0 kg se eleva 4.0 m con rapidez constante (g = 10 m/s2). ¿Energia potencial?', '120 J', ['60 J', '240 J', '30 J'], 'Epg = 3 * 10 * 4 = 120 J.', 'Epg = 120 J.', 'basic', 1160, 'Multiplica masa por gravedad y por la altura.'))
    q.append(make_mc('Resorte con k = 400 N/m se deforma 0.10 m. ¿Energia potencial elastica?', '2.0 J', ['4.0 J', '1.0 J', '8.0 J'], 'Epe = 0.5 * 400 * 0.01 = 2 J.', 'Epe = 2 J.', 'intermediate', 1200, 'Aplica la formula de energia elastica con la deformacion al cuadrado.'))
    q.append(make_mc('Se suelta una pelota desde 20 m sin rozamiento (g = 10 m/s2). ¿Rapidez al caer?', '20.0 m/s', ['14.1 m/s', '10.0 m/s', '25.0 m/s'], 'v = sqrt(2 * 10 * 20) = 20 m/s.', 'v = 20 m/s.', 'intermediate', 1220, 'Iguala la energia potencial gravitatoria inicial a la cinetica final.'))
    q.append(make_mc('Motor realiza trabajo util de 15000 J en 30 s. ¿Potencia mecanica media?', '500 W', ['450 W', '600 W', '300 W'], 'P = 15000 / 30 = 500 W.', 'P = 500 W.', 'basic', 1150, 'Divide el trabajo util entre el intervalo de tiempo transcurrido.'))
    q.append(make_mc('Trineo de 10 kg con v0 = 4 m/s recibe trabajo neto de 100 J. ¿Rapidez final?', '6.0 m/s', ['5.0 m/s', '7.2 m/s', '8.0 m/s'], 'Ek_f = 80 + 100 = 180 J -> vf = 6 m/s.', 'vf = 6 m/s.', 'intermediate', 1230, 'Suma el trabajo neto a la energia cinetica inicial.'))
    q.append(make_mc('Vagoneta pasa por A (h=15 m, v=10 m/s). ¿Rapidez en B a h=10 m? (g=10 m/s2)', '14.1 m/s', ['12.5 m/s', '16.0 m/s', '10.0 m/s'], 'vB = sqrt(100 + 2*10*5) = 14.1 m/s.', 'vB = 14.1 m/s.', 'advanced', 1260, 'Aplica conservacion de la energia mecanica total.'))
    q.append(make_mc('Fuerza de 50 N a 60° respecto al desplazamiento de 10 m. ¿Trabajo? (cos 60 = 0.50)', '250 J', ['500 J', '433 J', '125 J'], 'W = 50 * 10 * 0.5 = 250 J.', 'W = 250 J.', 'basic', 1160, 'Multiplica fuerza, distancia y el coseno del angulo formado.'))
    q.append(make_mc('Grua con P = 2000 W sube 400 kg a rapidez constante (g = 10 m/s2). ¿Rapidez?', '0.50 m/s', ['0.25 m/s', '1.0 m/s', '2.0 m/s'], 'v = 2000 / 4000 = 0.50 m/s.', 'v = 0.5 m/s.', 'intermediate', 1220, 'Divide la potencia entre el peso del cargamento.'))
    # Teoricas
    q.append(make_mc('Si una fuerza es perpendicular al desplazamiento en todo instante, su trabajo es:', 'Estrictamente nulo', ['Maximo y positivo', 'Maximo y negativo', 'Dependiente de la masa'], 'cos(90) = 0 implica trabajo nulo.', 'W = 0.', 'basic', 1140, '¿Que valor toma el coseno de 90 grados en el trabajo?'))
    q.append(make_mc('Segun el Teorema del Trabajo y la Energia Cinetica, el trabajo neto es igual a:', 'La variacion de energia cinetica', ['La perdida de energia potencial', 'La energia mecanica disipada', 'La potencia instantanea media'], 'W_neto = Delta Ek.', 'W_neto = Ek_f - Ek_i.', 'basic', 1160, '¿Que variacion energetica cuantifica el trabajo de todas las fuerzas?'))
    q.append(make_mc('¿Cual de las siguientes fuerzas es considerada no conservativa?', 'La fuerza de rozamiento cinetico', ['La atraccion gravitatoria', 'La fuerza elastica del muelle', 'La fuerza electrostatica'], 'La friccion disipa energia mecanica en calor.', 'Rozamiento = fuerza disipativa.', 'basic', 1150, '¿Que fuerza degrada energia en forma de calor irrecuperable?'))
    q.append(make_mc('En un sistema donde solo actuan fuerzas conservativas, se conserva:', 'La energia mecanica total', ['La velocidad de cada particula', 'La aceleracion instantanea', 'La energia potencial gravitatoria'], 'Sin disipacion, Em permanece constante.', 'Em = Ek + Ep = constante.', 'basic', 1150, '¿Que combinacion de energia cinetica y potencial permanece constante?'))
    q.append(make_mc('En un pendulo ideal sin rozamiento, la rapidez es maxima en:', 'El punto mas bajo de su trayectoria', ['Los extremos de maxima altura', 'Cualquier posicion intermedia', 'La rapidez es constante en el arco'], 'Ep minima en el fondo implica Ek maxima.', 'h minima => v maxima.', 'intermediate', 1210, '¿En que punto la altura y por tanto la energia potencial es minima?'))
    q.append(make_mc('Una persona sostiene una valija inmóvil a cierta altura durante 15 min. ¿Trabajo?', 'Cero, porque el desplazamiento es nulo', ['Un trabajo mecanico elevado', 'Un trabajo dependiente del tiempo', 'Un trabajo proporcional a la masa'], 'Sin desplazamiento (d=0) el trabajo es nulo.', 'W = F * 0 = 0.', 'basic', 1150, '¿Hubo algun cambio de posicion espacial de la valija?'))
    q.append(make_mc('La unidad del Sistema Internacional para energia y trabajo es el Joule, igual a:', 'Newton por metro (kg·m²/s²)', ['Watt por segundo al cuadrado', 'Newton sobre metro cuadrado', 'Kilogramo por metro sobre segundo'], '1 J = 1 N * 1 m = 1 kg*m2/s2.', '1 Joule = 1 N * m.', 'basic', 1140, 'Recuerda que trabajo es fuerza multiplicada por desplazamiento.'))
    q.append(make_mc('Si la rapidez de un vehiculo se triplica, su energia cinetica:', 'Se multiplica por nueve veces', ['Se multiplica por tres veces', 'Se multiplica por seis veces', 'Se reduce a la tercera parte'], 'Ek proporcional a v^2: (3v)^2 = 9v^2.', '3 al cuadrado es 9.', 'intermediate', 1200, 'Eleva el factor de aumento de velocidad al exponente dos.'))
    q.append(make_mc('El trabajo realizado por el rozamiento cinetico sobre un cuerpo que desliza es:', 'Siempre de signo negativo', ['Siempre de signo positivo', 'Nulo en cualquier tramo', 'Positivo si sube una rampa'], 'Friccion opuesta al desplazamiento: cos(180) = -1.', 'W < 0.', 'intermediate', 1210, '¿Que angulo forma la fuerza de rozamiento con el sentido de avance?'))
    q.append(make_mc('En un choque inelastico real, la energia mecanica total:', 'Disminuye al disiparse en calor y sonido', ['Se conserva perfectamente constante', 'Aumenta por liberacion elastica', 'Se transforma en potencial neta'], 'Parte de la energia se degrada en calor y deformacion.', 'Energia mecanica se degrada.', 'intermediate', 1220, '¿De donde proviene el sonido y la temperatura producida en el impacto?'))
    return q


def get_questions_cantidad_movimiento_extra():
    q = []
    # Ejercicios
    q.append(make_mc('¿Cual es el momento lineal de un proyectil de 0.05 kg que viaja a 400 m/s?', '20 kg·m/s', ['2.0 kg·m/s', '200 kg·m/s', '10 kg·m/s'], 'p = m*v = 0.05 * 400 = 20 kg*m/s.', 'p = 20 kg*m/s.', 'basic', 1150, 'Multiplica la masa por la velocidad vectorial.'))
    q.append(make_mc('Fuerza constante de 60 N actua durante 0.50 s sobre una pelota. ¿Impulso recibido?', '30 N·s', ['120 N·s', '15 N·s', '60 N·s'], 'I = F * Delta t = 60 * 0.50 = 30 N*s.', 'I = 30 N*s.', 'basic', 1150, 'Aplica el teorema del impulso multiplicando fuerza por tiempo.'))
    q.append(make_mc('Pelota de 0.40 kg lanzada a 15 m/s golpea una pared y rebota a 15 m/s en sentido opuesto. ¿Variacion de momento?', '12.0 kg·m/s', ['6.0 kg·m/s', '0.0 kg·m/s', '24.0 kg·m/s'], 'Delta p = m*(vf - vi) = 0.40*(15 - (-15)) = 0.40 * 30 = 12 kg*m/s.', 'Delta p = 12 kg*m/s.', 'intermediate', 1220, 'Recuerda que la velocidad es un vector: el rebote invierte su signo.'))
    q.append(make_mc('Un cuerpo de 2.0 kg a 6.0 m/s choca con otro de 4.0 kg en reposo y se unen (plastico). ¿Rapidez final?', '2.0 m/s', ['3.0 m/s', '1.5 m/s', '4.0 m/s'], 'Conservacion: 2*6 + 0 = (2+4)*vf -> 12 = 6*vf -> vf = 2 m/s.', 'vf = 12 / 6 = 2 m/s.', 'intermediate', 1210, 'Aplica la conservacion del momento lineal antes y despues del choque.'))
    q.append(make_mc('Un tirador de 70 kg dispara bala de 0.02 kg a 500 m/s. ¿Rapidez de retroceso del tirador?', '0.14 m/s', ['0.28 m/s', '1.40 m/s', '0.07 m/s'], '0 = 70*v_ret - 0.02*500 -> 70*v_ret = 10 -> v_ret = 0.14 m/s.', 'v_ret = 10 / 70 = 0.14 m/s.', 'intermediate', 1230, 'El momento lineal total inicial era cero: iguala los momentos opuestos.'))
    q.append(make_mc('Fuerza media frena un auto de 1000 kg desde 20 m/s hasta cero en 4.0 s. ¿Modulo de la fuerza media?', '5000 N', ['2500 N', '4000 N', '10000 N'], 'F_med = Delta p / Delta t = (1000*20) / 4 = 5000 N.', 'F = 20000 / 4 = 5000 N.', 'intermediate', 1210, 'Divide la variacion total del momento entre el tiempo de frenado.'))
    q.append(make_mc('Cuerpo de 3.0 kg con p = 18 kg·m/s. ¿Cual es su energia cinetica?', '54 J', ['27 J', '108 J', '36 J'], 'Ek = p^2 / (2m) = 324 / 6 = 54 J.', 'Ek = 18^2 / (2*3) = 54 J.', 'intermediate', 1240, 'Usa la formula que vincula energia cinetica con el momento al cuadrado.'))
    q.append(make_mc('Un vagon de 5000 kg a 2.0 m/s choca y engancha a otro identico en reposo. ¿Rapidez conjunta?', '1.0 m/s', ['0.5 m/s', '1.5 m/s', '2.0 m/s'], 'vf = (5000*2) / 10000 = 1.0 m/s.', 'vf = 1.0 m/s.', 'basic', 1160, 'La masa total se duplica, por lo que la velocidad resultante se reduce a la mitad.'))
    q.append(make_mc('Fuerza variable tiene grafico F(t) triangular de base 6.0 s y altura 100 N. ¿Impulso total?', '300 N·s', ['600 N·s', '150 N·s', '200 N·s'], 'Area de triangulo = base * altura / 2 = 6 * 100 / 2 = 300 N*s.', 'I = 6 * 100 / 2 = 300 N*s.', 'intermediate', 1220, 'El impulso corresponde al area bajo la curva en el grafico fuerza-tiempo.'))
    q.append(make_mc('Dos patinadores en reposo se empujan mutuamente. El de 40 kg sale a 3.0 m/s. ¿Rapidez del de 60 kg?', '2.0 m/s', ['3.0 m/s', '1.5 m/s', '4.5 m/s'], '40 * 3.0 = 60 * v2 -> 120 = 60*v2 -> v2 = 2.0 m/s.', 'v2 = 120 / 60 = 2 m/s.', 'intermediate', 1200, 'Iguala las magnitudes de los momentos de ambos patinadores.'))
    # Teoricas
    q.append(make_mc('En cualquier sistema aislado sin fuerzas externas netas, se conserva:', 'La cantidad de movimiento lineal total', ['La energia cinetica exclusivamente', 'La aceleracion de cada particula', 'La energia potencial gravitatoria'], 'F_ext = 0 implica dp/dt = 0 => p_total constante.', 'p_total se conserva.', 'basic', 1140, '¿Que principio fundamental rige a los sistemas mecanicos aislados?'))
    q.append(make_mc('El Teorema del Impulso establece que el impulso de la fuerza neta es igual a:', 'La variacion de cantidad de movimiento', ['La energia mecanica transferida', 'El trabajo realizado por la fuerza', 'La aceleracion media del proceso'], 'I = F*Delta t = Delta p.', 'I = Delta p.', 'basic', 1150, '¿Que cambio en el estado de movimiento genera la accion de una fuerza en un tiempo?'))
    q.append(make_mc('En una colision perfectamente inelastica (plastica):', 'Los cuerpos quedan unidos tras el impacto', ['Se conserva la energia cinetica total', 'Los cuerpos rebotan sin deformacion', 'El momento lineal total no se conserva'], 'En choque plastico los objetos continúan con una velocidad comun.', 'Cuerpos unidos tras el choque.', 'basic', 1160, '¿Que rasgo distintivo presentan los objetos al finalizar un choque plastico?'))
    q.append(make_mc('En un choque perfectamente elastico se conservan simultaneamente:', 'El momento lineal y la energia cinetica', ['Solo la cantidad de movimiento lineal', 'Solo la energia potencial gravitatoria', 'La rapidez individual de cada cuerpo'], 'Choque elastico: Delta p = 0 y Delta Ek = 0.', 'Se conservan p y Ek.', 'intermediate', 1210, '¿Que tipo de colision no presenta perdida alguna de energia cinetica?'))
    q.append(make_mc('¿Por que los autos modernos tienen zonas deformables en el chasis?', 'Para aumentar el tiempo de choque y bajar la fuerza', ['Para evitar que el auto rebote hacia atras', 'Para conservar mayor cantidad de movimiento', 'Para reducir la masa del vehiculo en el choque'], 'Mayor Delta t implica menor F_media para el mismo Delta p.', 'Mayor tiempo reduce la fuerza de impacto.', 'intermediate', 1220, 'Fijate en la relacion F_media = Delta p / Delta t.'))
    q.append(make_mc('El airbag de un automovil protege al pasajero principalmente porque:', 'Prolonga el tiempo en que se detiene el pasajero', ['Disminuye el cambio de momento lineal total', 'Elimina completamente la inercia del cuerpo', 'Aumenta la fuerza sobre el torax del ocupante'], 'Al extender Delta t, disminuye la fuerza de impacto recibida.', 'Mayor Delta t disminuye la fuerza sobre el cuerpo.', 'intermediate', 1220, 'Relaciona la fuerza media con el tiempo que tarda en frenar la cabeza.'))
    q.append(make_mc('La cantidad de movimiento lineal es una magnitud de naturaleza:', 'Vectorial con misma direccion que la velocidad', ['Escalar definida positiva en todo caso', 'Vectorial perpendicular a la velocidad', 'Adimensional en el Sistema Internacional'], 'p = m*v comparte direccion y sentido con v.', 'p es un vector paralelo a v.', 'basic', 1140, 'Dado que la masa es escalar positiva, ¿que direccion adopta el producto m*v?'))
    q.append(make_mc('En una explosion interna de un objeto inicialmente en reposo:', 'El centro de masa permanece inmóvil', ['Todos los fragmentos van en igual direccion', 'Se pierde la conservacion del momento lineal', 'La energia cinetica inicial era maxima'], 'Fuerzas internas conservan el momento total nulo.', 'Momento total sigue siendo cero.', 'advanced', 1250, 'Si no intervinieron fuerzas externas, ¿cambia el momento del sistema?'))
    q.append(make_mc('La unidad del Sistema Internacional para el impulso es N·s, equivalente a:', 'kg·m/s', ['kg·m²/s', 'kg·m/s²', 'Joule·segundo'], '1 N*s = (kg*m/s2)*s = 1 kg*m/s.', 'N*s = kg*m/s.', 'basic', 1140, 'Recuerda que el impulso equivale a la variacion del momento lineal.'))
    q.append(make_mc('Si una pelota de masa m rebota elasticamente contra el piso a rapidez v:', 'El cambio de momento tiene modulo 2mv', ['El cambio de momento es exactamente cero', 'El cambio de momento tiene modulo mv', 'El momento cinetico se anula al tocar'], 'Delta p = m*v - m*(-v) = 2mv.', 'Delta p = 2mv.', 'intermediate', 1230, 'Resta el vector velocidad final menos el vector inicial opuesto.'))
    return q

def get_questions_mov_circular_extra():
    q = []
