    q.append(make_mc('Rueda de 0.40 m de radio gira a velocidad angular constante de 10 rad/s. ¿Rapidez tangencial?', '4.0 m/s', ['2.5 m/s', '40 m/s', '0.04 m/s'], 'v = omega * r = 10 * 0.40 = 4.0 m/s.', 'v = 4 m/s.', 'basic', 1150, 'Multiplica la velocidad angular por el radio del circulo.'))
