    q.append(make_mc('A una altura h igual al radio terrestre (r = 2R), ¿que valor tiene la gravedad?', '2.45 m/s²', ['4.90 m/s²', '9.80 m/s²', '1.22 m/s²'], 'g(2R) = g0 / 2^2 = 9.8 / 4 = 2.45 m/s2.', 'g = g0 / 4 = 2.45 m/s2.', 'intermediate', 1210, 'La gravedad cae con el cuadrado de la distancia al centro del planeta.'))
    q.append(make_mc('¿Cual es la velocidad orbital aproximada en orbita baja terrestre? (r = 6.4e6 m, g = 9.8 m/s2)', '7.9 km/s', ['11.2 km/s', '5.5 km/s', '9.8 km/s'], 'v_orb = sqrt(g * R) = sqrt(9.8 * 6.4e6) = 7919 m/s = 7.9 km/s.', 'v = sqrt(g*R) = 7.9 km/s.', 'intermediate', 1230, 'Iguala la fuerza gravitatoria a la centripeta y despeja la velocidad.'))
    q.append(make_mc('La velocidad de escape desde la superficie terrestre vale aproximadamente:', '11.2 km/s', ['7.9 km/s', '16.7 km/s', '22.4 km/s'], 'v_esc = sqrt(2 * g * R) = sqrt(2) * 7.9 = 11.2 km/s.', 'v_esc = sqrt(2)*v_orb = 11.2 km/s.', 'intermediate', 1220, 'Recuerda que la velocidad de escape es raiz de dos veces la orbital.'))
