    q.append(make_mc('Si la distancia entre dos planetas se reduce a la mitad, ¿por cuanto se multiplica su atraccion?', 'Cuatro veces', ['Dos veces', 'Ocho veces', 'Permanece igual'], 'F proporcional a 1/r^2: (1/0.5)^2 = 4.', 'F se multiplica por 4.', 'basic', 1150, 'Eleva el factor de reduccion de distancia al cuadrado inverso.'))
    q.append(make_mc('Un planeta tiene el doble de masa que la Tierra e igual radio. ¿Gravedad superficial?', '19.6 m/s²', ['9.8 m/s²', '4.9 m/s²', '39.2 m/s²'], 'g proporcional a M: g = 2 * 9.8 = 19.6 m/s2.', 'g = 2 * 9.8 = 19.6 m/s2.', 'basic', 1150, 'La gravedad es directamente proporcional a la masa del astro.'))
    q.append(make_mc('Periodo de un satelite geoestacionario alrededor de la Tierra:', '24 horas', ['12 horas', '48 horas', '1.5 horas'], 'Por definicion debe coincidir con la rotacion terrestre: 24 h.', 'T = 24 h = 1 dia.', 'basic', 1130, '¿Cuanto tarda la Tierra en dar una rotacion completa sobre su eje?'))
    # Teoricas
    q.append(make_mc('La Ley de Gravitacion Universal de Newton establece que la fuerza:', 'Decrece con el cuadrado de la distancia', ['Decrece linealmente con la distancia', 'Es independiente de la masa de los cuerpos', 'Es siempre repulsiva a distancias cortas'], 'F = G*m1*m2 / r^2: ley del inverso del cuadrado.', 'Ley del inverso del cuadrado.', 'basic', 1140, '¿Que potencia tiene la distancia en el denominador de la ley de Newton?'))
    q.append(make_mc('La constante de gravitacion universal G:', 'Es la misma en cualquier region del universo', ['Varia segun la altura sobre el mar', 'Depende de la temperatura del medio', 'Es valida unicamente en el Sistema Solar'], 'G es una constante universal fundamental de la fisica.', 'G es constante universal escalar.', 'basic', 1140, '¿Depende el valor de G del planeta o lugar donde se mida?'))
    q.append(make_mc('Segun la Primera Ley de Kepler, las orbitas planetarias son:', 'Elipses con el Sol en uno de los focos', ['Circulos perfectos centrados en el Sol', 'Parabolas abiertas hacia el espacio', 'Espirales convergentes al centro solar'], 'Primera Ley: orbitas elipticas con el Sol en un foco.', 'Elipses con el Sol en un foco.', 'basic', 1140, '¿Que figura conica descubrio Kepler en la orbita de Marte?'))
    q.append(make_mc('Segun la Segunda Ley de Kepler, el radio vector que une el planeta al Sol:', 'Barre areas iguales en tiempos iguales', ['Se mantiene constante en modulo y sentido', 'Tiene rapidez lineal uniforme en la orbita', 'Acelera unicamente en el afelio'], 'Ley de las areas: velocidad areolar constante.', 'Barre areas iguales en tiempos iguales.', 'intermediate', 1210, '¿Que magnitud geometrica se conserva proporcional al tiempo transcurrido?'))
    q.append(make_mc('El punto de la orbita planetaria mas cercano al Sol se denomina:', 'Perihelio', ['Afelio', 'Apogeo', 'Perigeo'], 'Perihelio: minima distancia al Sol; afelio: maxima.', 'Perihelio = punto mas cercano.', 'basic', 1130, 'El prefijo peri indica cercania y helios significa Sol.'))
    q.append(make_mc('Un planeta se desplaza con mayor rapidez orbital cuando pasa por:', 'El perihelio (mas cercano al Sol)', ['El afelio (mas lejano del Sol)', 'Los puntos medios de la elipse', 'La rapidez es estrictamente constante'], 'Por conservacion del momento angular, r menor implica v mayor.', 'Menor distancia => mayor rapidez orbital.', 'intermediate', 1210, 'Aplica la Segunda Ley de Kepler en la zona mas proxima al Sol.'))
    q.append(make_mc('La sensacion de ingravidez de los astronautas en la estacion espacial se debe a:', 'Que se encuentran en estado de caida libre continua', ['Que la gravedad es exactamente cero en el espacio', 'Que el campo magnetico compensa el peso', 'Que la atmosfera empuja el modulo hacia arriba'], 'Orbitar es caer libremente de forma continua alrededor del planeta.', 'Caida libre permanente en orbita.', 'intermediate', 1230, '¿Desaparece la fuerza gravitatoria a 400 km de altura o sigue actuando en caida libre?'))
    q.append(make_mc('La Tercera Ley de Kepler relaciona los periodos orbitales T y semiejes a como:', 'T² proporcional a a³', ['T proporcional a a', 'T³ proporcional a a²', 'T² proporcional a a'], 'T^2 / a^3 = constante para todos los planetas del Sol.', 'T² es proporcional a a³.', 'basic', 1150, '¿Que exponente lleva el periodo y cual el radio o semieje mayor?'))
    q.append(make_mc('El valor de la aceleracion de la gravedad g en la superficie depende de:', 'La masa y el radio del planeta considerado', ['La masa del objeto que esta cayendo', 'La velocidad inicial con que cae el cuerpo', 'La temperatura atmosferica reinante'], 'g = G*M / R^2 solo depende del planeta.', 'g = G*M / R^2.', 'basic', 1140, 'Recuerda que todos los cuerpos caen con la misma aceleracion independientemente de su masa.'))
    q.append(make_mc('Las mareas oceanicas en la Tierra se originan fundamentalmente por:', 'El gradiente de atraccion gravitatoria de la Luna y Sol', ['El calor emitido por la radiacion solar diurna', 'Las corrientes de vientos alisios marinos', 'El campo magnetico dipolar del nucleo'], 'La diferencia de fuerza gravitatoria entre el lado cercano y lejano genera la marea.', 'Fuerzas de marea por gradiente gravitatorio.', 'intermediate', 1220, '¿La atraccion de la Luna es mas fuerte en la cara de la Tierra mas proxima a ella?'))
