def get_questions_estatica_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Fuerza de 25 N actua perpendicular a palanca con brazo de 0.80 m. ¿Torque?', '20 N·m', ['25 N·m', '16 N·m', '31 N·m'], 'tau = F * d = 25 * 0.80 = 20 N*m.', 'tau = 20 N*m.', 'basic', 1150, 'Multiplica fuerza por brazo de palanca cuando son perpendiculares.'))
    q.append(make_mc('Barra de 4.0 m apoyada en el centro tiene peso de 30 N a 1.0 m del apoyo. ¿Fuerza en el extremo (2 m) para equilibrar?', '15 N', ['30 N', '60 N', '7.5 N'], '30 * 1.0 = F * 2.0 -> F = 15 N.', 'F = 30 / 2 = 15 N.', 'basic', 1160, 'Iguala los torques en sentido horario y antihorario respecto al apoyo.'))
    q.append(make_mc('Lampara de 12 kg cuelga de dos cuerdas simetricas a 30° de la horizontal (g = 10 m/s2). ¿Tension en cada cuerda?', '120 N', ['60 N', '240 N', '208 N'], '2*T*sen(30) = mg -> 2*T*0.5 = 120 -> T = 120 N.', 'T = 120 / (2*0.5) = 120 N.', 'intermediate', 1230, 'Plantea el equilibrio vertical sumando las componentes verticales de ambas tensiones.'))
    q.append(make_mc('Fuerza de 50 N a 30° respecto a una barra de 2.0 m. ¿Modulo del torque? (sen 30 = 0.50)', '50 N·m', ['100 N·m', '86.6 N·m', '25 N·m'], 'tau = F * r * sen(30) = 50 * 2 * 0.5 = 50 N*m.', 'tau = 50 N*m.', 'basic', 1160, 'Multiplica fuerza, longitud del brazo y el seno del angulo.'))
    q.append(make_mc('Regla uniforme de 1.0 m y 2.0 N de peso. ¿En que posicion se ubica su centro de gravedad?', 'En la marca de 0.50 m', ['En la marca de 0.25 m', 'En la marca de 0.75 m', 'En el extremo de 1.0 m'], 'En cuerpos homogeneos simetricos el centro de masa esta en el centro geometrico.', 'x_cm = L/2 = 0.50 m.', 'basic', 1130, '¿Donde se ubica el punto medio de un objeto alargado y homogeneo?'))
    q.append(make_mc('Para aflojar una tuerca se necesita un torque de 60 N·m con llave de 0.30 m. ¿Fuerza minima perpendicular?', '200 N', ['180 N', '150 N', '300 N'], 'F = tau / d = 60 / 0.30 = 200 N.', 'F = 60 / 0.3 = 200 N.', 'basic', 1150, 'Divide el torque requerido entre la longitud de la herramienta.'))
    q.append(make_mc('Sobre un punto actuan F1 = 30 N hacia arriba y F2 = 40 N a la derecha. ¿Modulo de la fuerza equilibrante?', '50 N', ['70 N', '10 N', '35 N'], 'R = sqrt(30^2 + 40^2) = 50 N. La equilibrante tiene igual modulo.', 'Modulo de equilibrante = 50 N.', 'intermediate', 1210, 'La fuerza equilibrante tiene el mismo modulo que la resultante de las fuerzas dadas.'))
    q.append(make_mc('Viga horizontal uniforme de 6.0 m y 100 N de peso apoyada en ambos extremos A y B. ¿Fuerza de soporte en A?', '50 N', ['100 N', '25 N', '75 N'], 'Por simetria el peso se divide en partes iguales: 100 / 2 = 50 N.', 'R_A = 50 N.', 'basic', 1140, 'Al estar apoyada simetricamente, ¿como se reparte la carga entre los apoyos?'))
    q.append(make_mc('Palanca de primer genero tiene brazo de fuerza de 1.5 m y brazo de resistencia de 0.5 m. ¿Ventaja mecanica?', '3.0', ['0.33', '2.0', '1.0'], 'VM = brazo_fuerza / brazo_resistencia = 1.5 / 0.5 = 3.0.', 'VM = 3.', 'basic', 1150, 'Divide la longitud del brazo de fuerza entre el de resistencia.'))
    q.append(make_mc('Cuerpo en equilibrio sobre plano inclinado a 37° sin deslizar (g=10 m/s2). ¿Fuerza de rozamiento estatico de 10 kg? (sen 37 = 0.60)', '60 N', ['80 N', '100 N', '48 N'], 'f_re = Px = m*g*sen(37) = 10 * 10 * 0.60 = 60 N.', 'f_re = 60 N.', 'intermediate', 1210, 'La friccion estatica equilibra exactamente la componente del peso en el plano.'))
    # Teoricas
    q.append(make_mc('Para que un cuerpo rigido este en equilibrio estatico completo se deben cumplir:', 'Suma de fuerzas nula y suma de torques nula', ['Solo suma de fuerzas igual a cero', 'Solo suma de torques igual a cero', 'Que la velocidad sea distinta de cero'], 'Primera condicion: suma F = 0; Segunda condicion: suma tau = 0.', 'Equilibrio traslacional y rotacional simultaneos.', 'basic', 1140, '¿Que dos condiciones garantizan que un objeto no se traslade ni empiece a girar?'))
    q.append(make_mc('El momento de una fuerza (torque) respecto a un punto mide:', 'La capacidad de la fuerza de producir rotacion', ['La cantidad de movimiento lineal total', 'El trabajo desarrollado en una trayectoria', 'La deformacion permanente del material'], 'El torque cuantifica la tendencia al giro respecto a un eje.', 'Torque = efecto rotacional de una fuerza.', 'basic', 1140, '¿Que tipo de movimiento angular provoca la aplicacion de un torque?'))
    q.append(make_mc('El brazo de palanca de una fuerza se define formalmente como:', 'La distancia perpendicular de la linea de accion al eje', ['La longitud total de la barra que soporta la carga', 'La distancia entre el punto de apoyo y el piso', 'La distancia paralela a la fuerza aplicada'], 'Es la distancia minima (perpendicular) de la recta de accion al pivote.', 'Distancia perpendicular de la linea de fuerza al pivote.', 'intermediate', 1220, '¿Como debe medirse la distancia entre el eje de giro y la recta de la fuerza?'))
    q.append(make_mc('Si la linea de accion de una fuerza pasa exactamente por el eje de giro:', 'El torque producido es estrictamente nulo', ['El torque producido es maximo positivo', 'El torque producido es maximo negativo', 'El cuerpo acelera bruscamente en giro'], 'Brazo d = 0 implica tau = F * 0 = 0.', 'Brazo nulo => torque cero.', 'basic', 1150, '¿Existe alguna distancia perpendicular entre el punto de giro y la fuerza?'))
    q.append(make_mc('Un cuerpo apoyado se encuentra en equilibrio estable cuando:', 'Al inclinarlo levemente su centro de gravedad se eleva', ['Al inclinarlo levemente su centro de gravedad desciende', 'Cualquier inclinacion lo deja en nueva posicion neutra', 'Su base de sustentacion es un unico punto agudo'], 'El centro de gravedad sube y el peso genera un torque restaurador.', 'Equilibrio estable: centro de masa se eleva al perturbar.', 'intermediate', 1230, '¿Que le ocurre a la altura del centro de masa de una botella apoyada al ladearla un poco?'))
    q.append(make_mc('En una tijera de podar (palanca), la fuerza que se aplica en los mangos:', 'Se multiplica en las cuchillas por tener menor brazo', ['Se reduce a la mitad por conservacion de energia', 'Se anula en el punto de apoyo articulado', 'Es identica en valor a la que reciben las ramas'], 'VM = brazo_potencia / brazo_resistencia > 1 magnifica la fuerza.', 'Mayor brazo en mangos que en hojas amplifica la fuerza.', 'intermediate', 1210, '¿Como es la longitud de los mangos comparada con la de las cuchillas cortas?'))
    q.append(make_mc('La unidad del torque en el Sistema Internacional es:', 'Newton·metro (N·m)', ['Joule (J)', 'Watt (W)', 'Pascal (Pa)'], 'Aunque dimensionalmente sea N*m, no se usa Joule para evitar confusion con energia.', 'N·m.', 'basic', 1140, 'Multiplica la unidad de fuerza por la de distancia en el SI.'))
    q.append(make_mc('Un par de fuerzas (cupla) consiste en:', 'Dos fuerzas iguales, paralelas y de sentidos opuestos', ['Dos fuerzas perpendiculares del mismo modulo', 'Dos fuerzas concurrentes en el mismo punto', 'Dos fuerzas aplicadas sobre cuerpos separados'], 'Cupla: resultante nula pero torque neto no nulo.', 'Fuerzas de igual modulo, direccion paralela y sentido contrario.', 'intermediate', 1220, 'Pensa en el volante de un auto manejado con las dos manos.')),
    q.append(make_mc('El centro de gravedad de un cuerpo coincide con su centro de masa cuando:', 'El campo gravitatorio es uniforme en toda su extension', ['El cuerpo tiene forma perfectamente esferica', 'El cuerpo carece de masa inercial medible', 'El objeto se encuentra en el espacio exterior'], 'Si g es constante en todo el cuerpo, CG coincide con CM.', 'g uniforme => CG coincide con CM.', 'intermediate', 1230, '¿Que condicion debe cumplir la aceleracion gravitatoria a lo largo del cuerpo?'))
    q.append(make_mc('Si se empuja una puerta por su borde exterior en vez de cerca de la bisagra:', 'Se requiere menos fuerza para lograr el mismo torque', ['Se necesita mucha mas fuerza para hacerla girar', 'El torque resultante es exactamente igual a cero', 'La puerta no puede rotar por falta de friccion'], 'Mayor brazo d permite aplicar menor fuerza F para igual tau.', 'Mayor brazo requiere menor fuerza.', 'basic', 1140, '¿Por que el picaporte se ubica siempre en el extremo opuesto a las bisagras?'))
    return q


def get_questions_fluidos_extra():
    q = []
    # Ejercicios
    q.append(make_mc('¿Cual es la presion hidrostatica a 10 m de profundidad en agua dulce? (rho = 1000 kg/m3, g = 10 m/s2)', '100 kPa', ['10 kPa', '1000 kPa', '50 kPa'], 'P = rho*g*h = 1000 * 10 * 10 = 100000 Pa = 100 kPa.', 'P = 100000 Pa.', 'basic', 1150, 'Aplica la formula fundamental de la hidrostatica multiplicando densidad, gravedad y profundidad.'))
    q.append(make_mc('Bloque de volumen 0.02 m3 esta totalmente sumergido en agua (rho = 1000 kg/m3, g = 10 m/s2). ¿Empuje?', '200 N', ['100 N', '400 N', '20 N'], 'E = rho*V*g = 1000 * 0.02 * 10 = 200 N.', 'E = 200 N.', 'basic', 1150, 'Aplica el principio de Arquimedes multiplicando la densidad del liquido por el volumen sumergido y g.'))
    q.append(make_mc('Prensa hidraulica tiene pistones de areas A1 = 5 cm2 y A2 = 100 cm2. Con F1 = 50 N, ¿fuerza F2 lograda?', '1000 N', ['500 N', '2000 N', '250 N'], 'F2 = F1 * (A2/A1) = 50 * (100/5) = 50 * 20 = 1000 N.', 'F2 = 1000 N.', 'intermediate', 1210, 'Aplica el principio de Pascal: la presion se transmite igual a ambos pistones.'))
    q.append(make_mc('Un objeto pesa 80 N en el aire y 60 N sumergido en agua. ¿Cuanto vale el empuje que recibe?', '20 N', ['140 N', '80 N', '60 N'], 'E = Peso_real - Peso_aparente = 80 - 60 = 20 N.', 'E = 80 - 60 = 20 N.', 'basic', 1150, 'La diferencia entre el peso real y el peso aparente sumergido es el empuje.'))
    q.append(make_mc('Fuerza de 600 N se distribuye sobre una superficie plana de 0.03 m2. ¿Cual es la presion ejercida?', '20 kPa', ['18 kPa', '30 kPa', '6 kPa'], 'P = F / A = 600 / 0.03 = 20000 Pa = 20 kPa.', 'P = 20000 Pa.', 'basic', 1140, 'Divide la fuerza normal entre la superficie sobre la que apoya.'))
    q.append(make_mc('Un iceberg de densidad 900 kg/m3 flota en agua de mar (1000 kg/m3). ¿Que porcentaje de su volumen se sumerge?', '90%', ['80%', '95%', '10%'], 'V_sum / V_tot = rho_cuerpo / rho_liquido = 900 / 1000 = 0.90 = 90%.', 'V_sum / V_tot = 90%.', 'intermediate', 1220, 'Para un cuerpo flotante, la fraccion sumergida es la razon entre densidades.'))
    q.append(make_mc('En un manometro en U con mercurio (rho = 13600 kg/m3), el desnivel es 0.10 m (g = 9.8 m/s2). ¿Presion manometrica?', '13.3 kPa', ['9.8 kPa', '136 kPa', '6.8 kPa'], 'P = 13600 * 9.8 * 0.10 = 13328 Pa = 13.3 kPa.', 'P = 13.3 kPa.', 'intermediate', 1220, 'Multiplica la densidad del mercurio por la gravedad y el desnivel de columnas.'))
    q.append(make_mc('Un tanque tiene un orificio a 5.0 m bajo la superficie libre del agua (g = 10 m/s2). Segun Torricelli, ¿rapidez de salida?', '10.0 m/s', ['7.0 m/s', '14.1 m/s', '5.0 m/s'], 'v = sqrt(2 * g * h) = sqrt(2 * 10 * 5) = 10.0 m/s.', 'v = sqrt(2*g*h) = 10 m/s.', 'intermediate', 1230, 'Aplica el teorema de Torricelli para la velocidad de desagüe de un fluido ideal.'))
    q.append(make_mc('Barometro de Torricelli al nivel del mar sostiene una columna de mercurio de altura estandar de:', '760 mm', ['1000 mm', '500 mm', '76 mm'], '1 atmosfera equivale a 760 mmHg = 101325 Pa.', 'h = 760 mmHg.', 'basic', 1130, '¿Cual es el valor clasico de la presion atmosferica en milimetros de mercurio?'))
    q.append(make_mc('Cuerpo de 2.0 kg y volumen 0.003 m3 se suelta en agua (rho = 1000 kg/m3, g = 10 m/s2). ¿El cuerpo flota o se hunde?', 'Flota, porque su densidad es 667 kg/m3', ['Se hunde, porque su peso supera al empuje', 'Queda en equilibrio indiferente en el fondo', 'Flota con solo un 10% bajo el agua'], 'rho = m / V = 2 / 0.003 = 667 kg/m3 < 1000 kg/m3 => flota.', 'Flota (densidad menor a la del agua).', 'intermediate', 1210, 'Calcula la densidad del cuerpo y comparala con la densidad del agua.'))
    # Teoricas
    q.append(make_mc('El Principio de Pascal establece que la presion aplicada a un fluido incompresible encerrado:', 'Se transmite con igual valor en todas las direcciones', ['Se disipa proporcionalmente con la distancia', 'Solo se transmite hacia el fondo del recipiente', 'Aumenta con el cuadrado del volumen del liquido'], 'La presion se comunica integramente a todos los puntos del fluido.', 'Presion se transmite igual en todo el fluido.', 'basic', 1140, '¿Como se propaga la presion ejercida en un circuito hidraulico cerrado?'))
    q.append(make_mc('Segun el Principio de Arquimedes, el empuje hidrostatico sobre un cuerpo sumergido es igual a:', 'El peso del volumen de fluido desalojado', ['El peso propio del cuerpo en el vacio', 'La presion atmosferica sobre la superficie', 'La masa del liquido multiplicada por el volumen'], 'E = peso del fluido desplazado.', 'E = m_fluido_desalojado * g.', 'basic', 1150, '¿El empuje equivale al peso de que sustancia especifica?'))
    q.append(make_mc('La presion hidrostatica en el interior de un liquido en reposo depende de:', 'La densidad del liquido y la profundidad considerada', ['El area total del fondo del recipiente', 'La forma geometrica de las paredes del vaso', 'El volumen total de liquido acumulado'], 'P = rho*g*h: depende solo de densidad, gravedad y profundidad.', 'P = rho * g * h.', 'basic', 1140, 'Recuerda la paradoja hidrostatica: ¿influye la forma del recipiente en la presion a igual cota?'))
    q.append(make_mc('La paradoja hidrostatica demuestra que dos recipientes con distinta forma e igual liquido y nivel:', 'Tienen la misma presion en sus fondos', ['Tienen mayor presion en el recipiente mas ancho', 'Tienen menor presion en el recipiente mas alto', 'Generan fuerzas de igual modulo en cualquier base'], 'A igual altura h e igual liquido, la presion en el fondo es identica.', 'Misma altura => misma presion en el fondo.', 'intermediate', 1220, '¿Depende la presion hidrostatica de la cantidad total de agua o unicamente de la columna de liquido?'))
    q.append(make_mc('Un submarino se sumerge a mayor profundidad regulando su peso aparente mediante:', 'El llenado o vaciado de sus tanques de lastre con agua', ['El cambio de velocidad de giro de las helices', 'La modificacion de la forma exterior de su casco', 'El encendido de sistemas de calefaccion interna'], 'Inyectar agua aumenta el peso medio para que P > E y descienda.', 'Tanques de lastre modifican la densidad media.', 'basic', 1160, '¿Que entra o sale de los tanques del submarino para alterar su flotabilidad?'))
    q.append(make_mc('La presion atmosferica a nivel del mar disminuye a medida que se asciende a una montaña porque:', 'La columna de aire sobre el observador es menor', ['La aceleracion de la gravedad se vuelve nula', 'La temperatura del aire es mas elevada arriba', 'La densidad del aire se multiplica por diez'], 'Al subir hay menor masa de aire suprayacente ejerciendo peso.', 'Menor columna de atmosfera por encima.', 'basic', 1150, '¿Hay mas o menos capas de aire pesando sobre vos en la cima de un cerro?'))
    q.append(make_mc('La unidad del Sistema Internacional para la presion es el Pascal (Pa), que equivale a:', 'Newton sobre metro cuadrado (N/m²)', ['Newton por metro lineal (N·m)', 'Joule sobre metro cubico (J/m³)', 'Kilogramo por metro sobre segundo'], '1 Pa = 1 N / 1 m2.', 'Pascal = N/m².', 'basic', 1130, 'Recuerda que presion es la fuerza normal distribuida por unidad de superficie.'))
    q.append(make_mc('Cuando un cuerpo colocado en agua flota en equilibrio estatico:', 'El modulo del empuje iguala al modulo de su peso', ['El empuje es mucho mayor que el peso del cuerpo', 'La densidad del cuerpo supera a la del agua', 'El peso aparente es el doble de su peso real'], 'Equilibrio vertical: E - P = 0 => E = P.', 'E = P en flotacion estatica.', 'basic', 1150, 'Para que no ascienda ni se hunda, ¿como deben ser las fuerzas verticales?'))
    q.append(make_mc('La tension superficial en liquidos se origina por:', 'Fuerzas de atraccion no compensadas en la superficie libre', ['La presion atmosferica empujando las moleculas', 'El campo gravitatorio actuando solo en la frontera', 'El rozamiento entre el liquido y el recipiente'], 'Moleculas de la superficie sufren atraccion neta hacia el interior.', 'Fuerzas cohesivas intermoleculares en la superficie.', 'intermediate', 1230, '¿Que experimentan las moleculas del borde libre que no tienen mas liquido por encima?'))
    q.append(make_mc('El principio de los vasos comunicantes indica que en tubos conectados con un mismo liquido:', 'El nivel alcanzado es el mismo en todos los brazos', ['El tubo mas ancho tendra mayor nivel de agua', 'El tubo mas angosto tendra menor nivel de agua', 'El liquido fluye indefinidamente de un tubo a otro'], 'Para igualar presiones en la base, los niveles de superficie libre coinciden.', 'Mismo nivel libre en vasos comunicantes.', 'basic', 1140, '¿Como se comportan las alturas de agua en recipientes conectados entre si?'))
    return q

def get_questions_ondas_extra():
    q = []
    # Ejercicios
    q.append(make_mc('Onda viaja a 340 m/s con frecuencia de 170 Hz. ¿Longitud de onda lambda?', '2.0 m', ['0.5 m', '4.0 m', '1.0 m'], 'lambda = v / f = 340 / 170 = 2.0 m.', 'lambda = 2 m.', 'basic', 1140, 'Divide la velocidad de propagacion entre la frecuencia.'))
    q.append(make_mc('Onda en cuerda tiene longitud de 0.50 m y periodo de 0.02 s. ¿Rapidez de propagacion?', '25.0 m/s', ['10.0 m/s', '50.0 m/s', '12.5 m/s'], 'v = lambda / T = 0.50 / 0.02 = 25 m/s.', 'v = 25 m/s.', 'basic', 1150, 'Divide la longitud de onda entre el periodo temporal.'))
    q.append(make_mc('Sonido viaja a 340 m/s y el eco de un acantilado se escucha a los 2.0 s. ¿Distancia al acantilado?', '340 m', ['680 m', '170 m', '510 m'], 'El sonido va y vuelve: d = v * t / 2 = 340 * 2 / 2 = 340 m.', 'd = 340 m.', 'intermediate', 1210, 'Recuerda que en el eco el sonido recorre dos veces la distancia (ida y vuelta).'))
    q.append(make_mc('Onda luminosa pasa de medio 1 (v1 = 3e8 m/s) a medio 2 (v2 = 2e8 m/s). Si f = 5e14 Hz, ¿lambda en medio 2?', '400 nm', ['600 nm', '500 nm', '300 nm'], 'lambda2 = v2 / f = 2e8 / 5e14 = 4e-7 m = 400 nm.', 'lambda2 = 400 nm.', 'intermediate', 1230, 'La frecuencia no cambia al refractarse; divide la nueva velocidad entre f.'))
    q.append(make_mc('Rayo incide a 30° en vidrio con n = 1.50 desde el aire (n1 = 1.00). ¿Seno del angulo refractado?', '0.33', ['0.50', '0.75', '0.25'], 'Snell: 1 * sen(30) = 1.5 * sen(r) -> sen(r) = 0.5 / 1.5 = 0.33.', 'sen(r) = 0.33.', 'intermediate', 1220, 'Aplica la Ley de Snell: n1 * sen(i) = n2 * sen(r).'))
    q.append(make_mc('Cuerda de 1.2 m fija en extremos vibra en su modo fundamental (1er armonico). ¿Longitud de onda?', '2.4 m', ['1.2 m', '0.6 m', '4.8 m'], 'En el fundamental L = lambda / 2 -> lambda = 2*L = 2.4 m.', 'lambda = 2.4 m.', 'intermediate', 1220, 'En el primer armonico la longitud de la cuerda equivale a media longitud de onda.'))
    q.append(make_mc('Una fuente emite 60 ondas completas cada 5.0 segundos. ¿Cual es su frecuencia en Hertz?', '12.0 Hz', ['6.0 Hz', '0.08 Hz', '24.0 Hz'], 'f = ciclos / tiempo = 60 / 5 = 12 Hz.', 'f = 12 Hz.', 'basic', 1140, 'Divide el numero de ciclos entre los segundos transcurridos.'))
    q.append(make_mc('Dos ondas coherentes en fase se superponen con amplitudes de 3.0 cm y 4.0 cm. ¿Amplitud resultante constructiva?', '7.0 cm', ['5.0 cm', '1.0 cm', '12.0 cm'], 'Interferencia constructiva: A_tot = A1 + A2 = 3 + 4 = 7 cm.', 'A = 7 cm.', 'basic', 1150, 'En interferencia constructiva pura las amplitudes individuales se suman directamente.'))
    q.append(make_mc('Ambulancia con sirena de 500 Hz se acerca a un observador en reposo. El tono percibido es:', 'Mas agudo (frecuencia mayor a 500 Hz)', ['Mas grave (frecuencia menor a 500 Hz)', 'Identico a 500 Hz en todo momento', 'Completamente inaudible por el movimiento'], 'Efecto Doppler: acercamiento comprime frentes de onda aumentando la frecuencia aparente.', 'f_aparente > 500 Hz.', 'basic', 1160, '¿Que le ocurre al tono sonoro de una fuente en movimiento cuando se aproxima hacia vos?'))
    q.append(make_mc('Rayo viaja de agua (n=1.33) a aire (n=1.00). ¿Seno del angulo critico limite para reflexion total?', '0.75', ['0.50', '0.67', '0.90'], 'sen(theta_c) = n2 / n1 = 1.00 / 1.33 = 0.75.', 'sen(theta_c) = 1 / 1.33 = 0.75.', 'advanced', 1260, 'Divide el indice de refraccion del medio exterior entre el del medio denso.'))
    # Teoricas
    q.append(make_mc('Una onda mecanica se caracteriza fundamentalmente porque:', 'Requiere un medio material elastico para propagarse', ['Se propaga unicamente en el vacio perfecto', 'Transporta materia a grandes distancias', 'Tiene siempre una rapidez igual a la de la luz'], 'Las ondas mecanicas necesitan soporte material (gas, liquido o solido).', 'Requiere medio material elastico.', 'basic', 1140, '¿Puede propagarse el sonido a traves del vacio del espacio exterior?'))
    q.append(make_mc('En una onda transversal, las particulas del medio oscilan:', 'Perpendicularmente a la direccion de propagacion', ['Paralelamente a la direccion de propagacion', 'En espirales abiertas hacia adelante', 'Permanecen completamente inmoviles'], 'Onda transversal: oscilacion perpendicular a la velocidad.', 'Oscilacion perpendicular a la propagacion.', 'basic', 1140, 'Pensa en las olas de una cuerda sacudida de arriba abajo.')),
    q.append(make_mc('En una onda sonora en el aire (onda longitudinal), las particulas oscilan:', 'Paralelamente a la direccion de propagacion', ['Perpendicularmente a la direccion de avance', 'En circulos transversales perfectos', 'Solo en el sentido del emisor inicial'], 'El sonido en fluidos es longitudinal: compresiones y rarefacciones paralelas.', 'Oscilacion paralela a la propagacion.', 'basic', 1150, '¿En que direccion se comprimen y descomprimen las capas de aire?'))
    q.append(make_mc('Cuando una onda pasa de un medio a otro con diferente rapidez (refraccion):', 'La frecuencia se mantiene estrictamente constante', ['La longitud de onda permanece constante', 'La velocidad de propagacion no varia', 'La amplitud se duplica en todo caso'], 'La frecuencia la determina el emisor y no cambia al refractar.', 'La frecuencia permanece constante.', 'intermediate', 1220, '¿Que propiedad de la oscilacion depende exclusivamente de la fuente original?'))
    q.append(make_mc('El fenomeno de difraccion consiste en:', 'La dispersion y curvado de la onda al sortear un obstaculo', ['El rebote de la onda al cambiar de medio denso', 'La disminucion de la frecuencia por absorcion', 'La separacion de la luz en colores componentes'], 'Difraccion: la onda rodea esquinas o pasa por rendijas angostas.', 'Onda rodea obstaculos o rendijas.', 'intermediate', 1210, '¿Como se llama la capacidad de una onda de rodear un borde y seguir avanzando?'))
    q.append(make_mc('Dos ondas generan interferencia totalmente destructiva en un punto cuando:', 'Llegan desfasadas en media longitud de onda (180°)', ['Llegan exactamente en fase simultaneamente', 'Tienen frecuencias completamente distintas', 'Sus rapideces de propagacion difieren en el medio'], 'Desfase de 180° (lambda/2) provoca cancelacion mutua de crestas y valles.', 'Desfase de 180° (lambda/2).', 'intermediate', 1220, '¿Que desfase hace coincidir la cresta de una onda con el valle de la otra?'))
