    q.append(make_mc('El tono o altura de un sonido esta determinado principalmente por:', 'La frecuencia de la vibracion de la onda sonora', ['La amplitud de presion de la onda sonora', 'La distancia entre el foco y el observador', 'La velocidad del viento en la atmosfera'], 'Mayor frecuencia = tono mas agudo; menor f = tono grave.', 'Tono depende de la frecuencia.', 'basic', 1140, '¿Que magnitud fisica distingue a una nota aguda de una nota grave?'))
    q.append(make_mc('El timbre de un instrumento musical nos permite:', 'Distinguir dos instrumentos que tocan la misma nota', ['Medir la velocidad a la que viaja el sonido', 'Calcular la distancia a la fuente acustica', 'Determinar el nivel sonoro en decibeles'], 'El timbre depende de la riqueza y proporcion de armonicos.', 'Timbre distingue fuentes por sus armonicos.', 'basic', 1150, '¿Por que una guitarra y un piano suenan diferente tocando la misma nota?'))
    q.append(make_mc('En una onda estacionaria, los puntos denominados nodos se caracterizan por:', 'Tener amplitud de oscilacion permanentemente nula', ['Oscilar con la maxima amplitud de la cuerda', 'Moverse con velocidad constante hacia adelante', 'Cambiar de posicion continuamente en el tiempo'], 'Nodos = interferencia destructiva continua (amplitud cero).', 'Nodos tienen amplitud cero.', 'basic', 1150, '¿Que amplitud de movimiento tienen los puntos fijos que no se mueven en la cuerda?'))
