    q.append(make_mc('Al conectar un voltimetro para medir la tension en una resistencia, se debe conectar:', 'En paralelo con la resistencia', ['En serie intercalado en la rama', 'Directamente entre el neutro y tierra', 'Desconectando antes la fuente de tension'], 'El voltimetro mide diferencia de potencial entre dos puntos (en paralelo).', 'Conexion en paralelo.', 'basic', 1150, 'Para comparar el potencial antes y despues del elemento, ¿como se conectan las puntas?'))
